void main() {
  var language = 'Dart';      // String, inferred
  int year = 2011;
  final launched = DateTime(year);
  const maxScore = 100;

  year += 14;
  print('$language turns ${year - launched.year}');  // Dart turns 14

  double ratio = 7 / 2;       // / always gives a double
  int whole = 7 ~/ 2;         // integer division
  print('$ratio $whole');     // 3.5 3

  print(int.parse('42') + maxScore);   // 142
  const a = [1, 2];
  const b = [1, 2];
  print(identical(a, b));     // true: const values are canonical
}

String greet(String? name) {
  if (name == null) return 'Hello, guest';
  return 'Hello, ${name.toUpperCase()}';   // promoted to String
}

class Config {
  late final String apiKey;              // set later, once
  late final int heavy = compute();      // lazy: runs on first read
  int compute() { print('computing'); return 42; }
}

void main() {
  print(greet(null));                    // Hello, guest
  print(greet('ana'));                   // Hello, ANA

  String? city;
  print(city?.length ?? 0);              // 0
  city ??= 'Oslo';
  print(city.length);                    // 4 (promoted after ??=)

  final c = Config()..apiKey = 'k-1';
  print(c.heavy);                        // computing / 42
  String? tag;
  print([1, ?tag].length);               // 1 (null-aware element)
}

String describe(int code) => switch (code) {
      200 || 201 => 'success',
      >= 400 && < 500 => 'client error',
      >= 500 => 'server error',
      _ => 'other',
    };

void main() {
  for (final c in [200, 404, 503, 302]) {
    print('$c ${describe(c)}');
  }
  // 200 success / 404 client error / 503 server error / 302 other

  var total = 0;
  for (var i = 1; i <= 10; i++) {
    if (i.isOdd) continue;
    total += i;
  }
  print(total);                     // 30

  final sb = StringBuffer()
    ..write('a')
    ..write('b');                   // cascade
  print(sb.toString().isEmpty ? 'empty' : sb);  // ab
}

String greet(String name, {String greeting = 'Hello', bool shout = false}) {
  final text = '$greeting, $name';
  return shout ? text.toUpperCase() : text;
}
int power(int base, [int exponent = 2]) {
  var result = 1;
  for (var i = 0; i < exponent; i++) result *= base;
  return result;
}

int Function() makeCounter() {
  var count = 0;
  return () => ++count;            // closure over count
}

void main() {
  print(greet('Ana'));                       // Hello, Ana
  print(greet('Bo', shout: true, greeting: 'Hi'));  // HI, BO
  print('${power(3)} ${power(2, 10)}');      // 9 1024

  final next = makeCounter();
  next();
  print(next());                             // 2
  print([1, 2, 3].map((x) => x * 10).toList());  // [10, 20, 30]
}

void main() {
  final fruits = ['apple', 'pear'];
  fruits.add('kiwi');                 // final list, mutable contents
  print(fruits.length);               // 3

  final emptySet = <String>{};        // {} alone would be a Map
  emptySet.addAll(['a', 'a', 'b']);
  print(emptySet);                    // {a, b}

  final stock = {'apple': 3, 'pear': 0};
  stock.update('kiwi', (n) => n + 1, ifAbsent: () => 1);
  print(stock['plum']);               // null
  print(stock);                       // {apple: 3, pear: 0, kiwi: 1}

  const showAll = false;
  final menu = [
    'home',
    if (showAll) 'admin',
    for (final f in fruits) f.toUpperCase(),
  ];
  print(menu);                        // [home, APPLE, PEAR, KIWI]
}

class Point {
  final double x;
  final double y;
  const Point(this.x, this.y);
  const Point.origin() : this(0, 0);
  factory Point.fromJson(Map<String, dynamic> json) =>
      Point((json['x'] as num).toDouble(), (json['y'] as num).toDouble());
  double get lengthSquared => x * x + y * y;   // a getter
  Point operator +(Point o) => Point(x + o.x, y + o.y);

  @override
  bool operator ==(Object other) => other is Point && other.x == x && other.y == y;
  @override
  int get hashCode => Object.hash(x, y);
  @override
  String toString() => 'Point($x, $y)';
}

void main() {
  final p = Point(3, 4) + Point.fromJson({'x': 1, 'y': 0});
  print(p);                                    // Point(4.0, 4.0)
  print(p.lengthSquared);                      // 32.0
  print(Point(1, 1) == Point(1, 1));           // true (custom ==)
  print(identical(const Point.origin(), const Point(0, 0)));  // true
}

void main() {
  final words = ['dart', 'is', 'fun', 'and', 'fast'];

  final lengths = words.map((w) => w.length);   // lazy Iterable<int>
  print(lengths.toList());                      // [4, 2, 3, 3, 4]

  final total = lengths.fold(0, (sum, n) => sum + n);
  print(total);                                 // 16

  print(words.where((w) => w.startsWith('f')).join(' '));  // fun fast
  print(words.any((w) => w.length > 3));        // true
  print([[1, 2], [3]].expand((l) => l).toList());          // [1, 2, 3]

  var calls = 0;
  final upper = words.map((w) { calls++; return w.toUpperCase(); });
  upper.first; upper.first;
  print(calls);                                 // 2 (lazy, re-run)

  for (final (i, w) in words.take(2).indexed) {
    print('$i:$w');                             // 0:dart  1:is
  }
}

concepts.body:
Dart can throw any non-null object, but by convention you throw:

- **`Exception`** subtypes for expected, recoverable failures (bad input, network down). `FormatException`, `IOException` and `TimeoutException` are common built-ins.
- **`Error`** subtypes for programming bugs (`RangeError`, `StateError`, `ArgumentError`, `TypeError`). Generally don't catch these; fix the code.

Handling:

```dart
try {
  final n = int.parse(input);
} on FormatException catch (e) {
  print('bad number: ${e.message}');
} catch (e, stackTrace) {
  rethrow;
} finally {
  cleanup();
}
```

`on Type` selects by type, `catch (e, s)` binds the exception and stack trace, and `rethrow` passes it on unchanged. `finally` always runs. Order clauses from most specific to most general.

Dart functions don't declare what they throw, so read API docs. Many APIs offer non-throwing variants: `int.tryParse` returns `null` instead of throwing.

Define your own exceptions by implementing `Exception`: `class PaymentDeclined implements Exception { ... }` with a useful `toString`.

In async code, errors from awaited futures are caught by the same `try`/`catch`. An uncaught exception terminates a command-line program; in Flutter it is reported and the frame continues, but your state may be inconsistent.

concepts.code:
class InsufficientFunds implements Exception {
  final int missing;
  InsufficientFunds(this.missing);
  @override String toString() => 'InsufficientFunds: need $missing more';
}
int withdraw(int balance, String input) {
  final amount = int.parse(input);            // may throw FormatException
  if (amount > balance) throw InsufficientFunds(amount - balance);
  return balance - amount;
}
void main() {
  for (final input in ['30', 'abc', '500']) {
    try {
      print('left: ${withdraw(100, input)}');
    } on FormatException catch (e) {
      print('not a number: ${e.source}');
    } on InsufficientFunds catch (e) {
      print(e);
    } finally {
      print('done $input');
    }
  }
  // left: 70 / done 30 / not a number: abc / done abc / InsufficientFunds: need 400 more / done 500
  print(int.tryParse('x') ?? -1);             // -1
}

abstract class Shape {
  const Shape();
  double get area;
  String describe() => '$runtimeType with area ${area.toStringAsFixed(1)}';
}
class Rect extends Shape {
  final double w, h;
  const Rect(this.w, this.h);
  @override
  double get area => w * h;
}
class Square extends Rect {
  const Square(double side) : super(side, side);
  @override
  String describe() => 'Square! ${super.describe()}';
}
class FakeShape implements Shape {      // contract only, nothing inherited
  @override double get area => 1;
  @override String describe() => 'fake';
}
void main() {
  final shapes = <Shape>[Rect(2, 3), Square(2), FakeShape()];
  for (final s in shapes) print(s.describe());
  // Rect with area 6.0 / Square! Square with area 4.0 / fake
}

concepts.body:
A **mixin** is a bundle of fields and methods that can be added to many classes without inheritance:

```dart
mixin Logger {
  void log(String msg) => print('[$runtimeType] $msg');
}
class Service with Logger { }
```

A class lists mixins after `with`, optionally after `extends`: `class Bird extends Animal with Flying, Singing`. The mixins are applied left to right, each layered on top of the previous one, so a later mixin can override a method from an earlier one and reach it through `super`. This **linearization** is how Dart avoids the diamond problem.

Restrict where a mixin can be used with `on`: `mixin Walker on Animal` can only be applied to subclasses of `Animal`, and inside it you can call `Animal`'s members and `super`.

Mixins can't have generative constructors. Since Dart 3, a class can only be used as a mixin if declared with `mixin` or `mixin class` (the latter is usable both as a normal class and a mixin).

In Flutter you'll write `class _MyState extends State<MyWidget> with SingleTickerProviderStateMixin` to give a state object the ability to drive animations, and models often use `with ChangeNotifier` or `extends ChangeNotifier`.

Prefer mixins for small, orthogonal capabilities. If you find a mixin needing lots of state from its host, composition (a field holding a helper object) may be clearer.

concepts.code:
abstract class Animal {
  String get name;
  String move() => '$name moves';
}
mixin Swimmer on Animal {
  @override
  String move() => '${super.move()} and swims';
}
mixin Flyer on Animal {
  @override
  String move() => '${super.move()} and flies';
  int altitude = 0;
}

class Duck extends Animal with Swimmer, Flyer {
  @override
  String get name => 'Duck';
}

void main() {
  final d = Duck()..altitude = 30;
  print(d.move());           // Duck moves and swims and flies
  print(d is Swimmer);       // true
  print(d.altitude);         // 30
}

concepts.body:
A simple enum lists values: `enum Status { idle, loading, done }`. Every enum has `values` (all values in order), each value has `index` and `name`, and `Status.values.byName('done')` looks one up by name.

**Enhanced enums** (Dart 2.17+) can carry data and behavior like a class:

```dart
enum Planet {
  mercury(3.3e23, 2.44e6),
  earth(5.97e24, 6.37e6);

  const Planet(this.mass, this.radius);
  final double mass, radius;
  double get gravity => 6.67e-11 * mass / (radius * radius);
}
```

Rules: values come first, followed by a semicolon; the constructor must be `const`; fields must be `final`. Enums can implement interfaces, use mixins and have static members and getters. They can't be extended or instantiated outside their declaration.

`switch` over an enum is **exhaustive**: if you handle every value, no `default` is needed, and adding a value later makes the compiler flag each switch that misses it. Avoid a catch-all `_` when you want this safety.

Enums are compared by identity, are `const`, and work well as `Map` keys. For JSON, store `value.name` and read back with `values.byName` (or a custom lookup with a fallback for unknown strings from a server).

concepts.code:
enum Plan implements Comparable<Plan> {
  free(0, maxProjects: 1),
  pro(9, maxProjects: 20),
  team(29, maxProjects: 100);
  const Plan(this.monthlyUsd, {required this.maxProjects});
  final int monthlyUsd;
  final int maxProjects;

  bool get isPaid => monthlyUsd > 0;
  @override
  int compareTo(Plan other) => monthlyUsd - other.monthlyUsd;
}

String badge(Plan p) => switch (p) {   // exhaustive, no default needed
      Plan.free => 'Free',
      Plan.pro => 'Pro ★',
      Plan.team => 'Team',
    };

void main() {
  print(Plan.values.where((p) => p.isPaid).map((p) => p.name).toList()); // [pro, team]
  print(badge(Plan.values.byName('pro')));   // Pro ★
  print(Plan.team.index);                    // 2
  print(Plan.free.compareTo(Plan.team) < 0); // true
}

concepts.body:
**Generics** let one class or function work with many types while keeping type safety: `List<String>`, `Map<String, int>`, `Future<User>`.

Declare type parameters in angle brackets:

```dart
class Box<T> {
  final T value;
  Box(this.value);
}
T firstOr<T>(List<T> items, T fallback) => items.isEmpty ? fallback : items.first;
```

Type arguments are usually inferred: `Box(3)` is a `Box<int>`. Write them explicitly when inference has nothing to go on, as in `<String>[]` or `Future<void>.delayed(...)`.

**Bounds** restrict type parameters: `class SortedList<T extends Comparable<T>>` can call `compareTo` on elements. Without a bound, `T` can only use `Object?` members.

Dart generics are **reified**: type arguments exist at run time. `list is List<int>` is a real check, and a `List<int>` won't accept a `String` even through a cast. (Contrast with Java's erasure.)

Generic classes are **covariant**: a `List<int>` is a `List<num>`. This is convenient but not fully static — adding a `double` to a `List<num>` that is really a `List<int>` throws at run time. The analyzer can warn about such cases with strict settings.

Use generics to remove duplication, but don't make APIs generic when one concrete type would do.

concepts.code:
class Cache<K, V> {
  final _store = <K, V>{};
  final V Function(K) _load;
  int misses = 0;
  Cache(this._load);
  V get(K key) => _store.putIfAbsent(key, () {
        misses++;
        return _load(key);
      });
}
T maxOf<T extends Comparable<T>>(List<T> items) =>
    items.reduce((a, b) => a.compareTo(b) >= 0 ? a : b);

void main() {
  final lengths = Cache<String, int>((s) => s.length);
  print(lengths.get('dart') + lengths.get('dart'));  // 8
  print(lengths.misses);                             // 1

  print(maxOf(['pear', 'apple', 'zebra']));          // zebra
  print(maxOf<num>([3, 9, 4]));  // 9 (int is Comparable<num>, not <int>)

  Object things = <int>[1, 2];
  print(things is List<int>);                        // true (reified)
  print(things is List<String>);                     // false
}

import 'dart:async';
Future<String> fetch(String what, int ms) async {
  await Future.delayed(Duration(milliseconds: ms));
  if (what.isEmpty) throw ArgumentError('empty request');
  return '$what loaded';
}
Future<void> main() async {
  final sw = Stopwatch()..start();
  final a = await fetch('user', 200);
  final b = await fetch('posts', 200);
  print('$a, $b in ~${sw.elapsedMilliseconds ~/ 100 * 100} ms'); // ~400 ms
  sw.reset();
  final (u, p) = await (fetch('user', 200), fetch('posts', 200)).wait;
  print('$u, $p in ~${sw.elapsedMilliseconds ~/ 100 * 100} ms'); // ~200 ms
  try {
    await fetch('', 10);
  } on ArgumentError catch (e) {
    print('failed: ${e.message}');          // failed: empty request
  }
  try {
    await fetch('slow', 500).timeout(const Duration(milliseconds: 50));
  } on TimeoutException {
    print('timed out');                     // timed out
  }
}

({int ok, int failed}) summarize(List<int> codes) {
  var ok = 0, failed = 0;
  for (final c in codes) {
    if (c case >= 200 && < 300) ok++; else failed++;
  }
  return (ok: ok, failed: failed);
}

String describe(Object? json) => switch (json) {
      {'type': 'user', 'name': String name, 'age': int age} when age >= 18 =>
        'adult $name',
      {'type': 'user', 'name': String name} => 'user $name',
      [int first, ...] => 'list starting with $first',
      null => 'nothing',
      _ => 'unknown',
    };

void main() {
  final (:ok, :failed) = summarize([200, 404, 201, 500]);
  print('$ok ok, $failed failed');                               // 2 ok, 2 failed
  print(describe({'type': 'user', 'name': 'Ana', 'age': 31}));   // adult Ana
  print(describe({'type': 'user', 'name': 'Bo'}));               // user Bo
  print(describe([7, 8]));                                       // list starting with 7
  print((1, 'a') == (1, 'a'));                                   // true
}

import 'dart:async';
Stream<int> countdown(int from) async* {
  for (var i = from; i > 0; i--) {
    await Future.delayed(const Duration(milliseconds: 10));
    yield i;
  }
}

Future<void> main() async {
  await for (final n in countdown(3)) {
    print(n);                                    // 3 2 1
  }

  final evens = countdown(6).where((n) => n.isEven).map((n) => n * 10);
  print(await evens.toList());                   // [60, 40, 20]

  final clicks = StreamController<String>.broadcast();
  final sub = clicks.stream.listen((c) => print('A got $c'));
  clicks.stream.where((c) => c == 'ok').listen((_) => print('B saw ok'));
  clicks..add('ok')..add('cancel');
  await Future<void>.delayed(Duration.zero);     // let events deliver
  await sub.cancel();
  await clicks.close();
  // A got ok / B saw ok / A got cancel
}

sealed class LoadState {}
class Loading extends LoadState {
  Loading(this.progress);
  final double progress;
}
class Loaded extends LoadState {
  Loaded(this.items);
  final List<String> items;
}
class Failed extends LoadState {
  Failed(this.message);
  final String message;
}
String render(LoadState s) => switch (s) {    // exhaustive: no default
      Loading(:final progress) => 'Loading ${(progress * 100).round()}%',
      Loaded(items: []) => 'Nothing yet',
      Loaded(:final items) => '${items.length} items',
      Failed(:final message) => 'Error: $message',
    };
void main() {
  print(render(Loading(0.25)));            // Loading 25%
  print(render(Loaded([])));               // Nothing yet
  print(render(Loaded(['a', 'b'])));       // 2 items
  print(render(Failed('offline')));        // Error: offline
}

concepts.body:
An **extension** adds members to a type you don't control:

```dart
extension StringCase on String {
  String get capitalized => isEmpty ? this : this[0].toUpperCase() + substring(1);
}
'dart'.capitalized; // Dart
```

Extensions can add methods, getters, setters and operators, and can be generic (`extension on List<T>`). They are resolved **statically**, based on the variable's static type: they don't work on `dynamic` values and can't override existing members. If two imported extensions conflict, hide one or call it explicitly: `StringCase('x').capitalized`. Flutter code often uses extensions such as `context.theme` helpers.

An **extension type** (Dart 3.3+) wraps an existing type with a new static interface and **no run-time cost**:

```dart
extension type UserId(int value) {
  bool get isValid => value > 0;
}
```

At compile time `UserId` is distinct from `int`, so you can't pass a raw int or an `OrderId` where a `UserId` is expected. At run time it *is* the int — no wrapper object is allocated. Add `implements int` to expose the representation type's members.

Because the wrapper is erased, `is` checks and casts see the underlying type, so extension types are not a security boundary. They shine for strongly typed IDs and units, and for JS interop (`dart:js_interop` is built on them).

concepts.code:
extension Stats on Iterable<num> {
  double get average => isEmpty ? 0 : fold<num>(0, (a, b) => a + b) / length;
}
extension DurationFormat on Duration {
  String get mmss =>
      '${inMinutes.toString().padLeft(2, '0')}:${(inSeconds % 60).toString().padLeft(2, '0')}';
}

extension type UserId(int value) {
  bool get isValid => value > 0;
}
extension type OrderId(int value) {}

String loadUser(UserId id) => id.isValid ? 'user #${id.value}' : 'invalid';

void main() {
  print([2, 4, 9].average);                       // 5.0
  print(const Duration(seconds: 125).mmss);       // 02:05

  final id = UserId(42);
  print(loadUser(id));                            // user #42
  // loadUser(OrderId(42));                       // compile error
  // loadUser(42);                                // compile error
  print((id as Object) is int);                   // true: erased at run time
}

// test/cart_test.dart
import 'package:test/test.dart';
class Cart {
  final _items = <String, double>{};
  void add(String name, double price) {
    if (price < 0) throw ArgumentError.value(price, 'price');
    _items[name] = price;
  }
  double get total => _items.values.fold(0, (a, b) => a + b);
  Future<String> checkout() async => 'paid ${total.toStringAsFixed(2)}';
}
void main() {
  group('Cart', () {
    late Cart cart;
    setUp(() => cart = Cart()..add('tea', 2.5));
    test('sums prices', () {
      cart.add('cake', 0.1);
      expect(cart.total, closeTo(2.6, 1e-9));
    });
    test('rejects negative prices', () {
      expect(() => cart.add('x', -1), throwsArgumentError);
    });
    test('checks out', () async => expect(await cart.checkout(), 'paid 2.50'));
  });
}

import 'dart:async';

Future<void> work() async {
  print('2 work starts (sync)');
  await null;                                  // yields to microtasks
  print('5 work resumes (microtask)');
}

void main() {
  print('1 main');
  Future(() => print('8 event: Future()'));
  Timer.run(() => print('9 event: Timer.run'));
  Future.delayed(Duration.zero, () => print('10 event: delayed zero'));
  scheduleMicrotask(() => print('4 microtask'));
  work();
  Future.value(0).then((_) => print('6 then on completed future'));
  Future.microtask(() => print('7 Future.microtask'));
  print('3 main ends');
}
// Output follows the numbers: sync code, then all microtasks
// in scheduling order, then events in order.

import 'dart:isolate';

int countPrimes(int limit) {
  var count = 0;
  for (var n = 2; n < limit; n++) {
    var prime = true;
    for (var d = 2; d * d <= n; d++) {
      if (n % d == 0) { prime = false; break; }
    }
    if (prime) count++;
  }
  return count;
}

Future<void> main() async {
  final sw = Stopwatch()..start();
  final results = await Future.wait([
    Isolate.run(() => countPrimes(2000000)),
    Isolate.run(() => countPrimes(1000000)),
  ]);
  print(results);                 // [148933, 78498] — computed in parallel
  print('main isolate stayed free: ${sw.elapsedMilliseconds} ms');
}
